from __future__ import annotations

import os
import re

from code_claim_verifier.types import TypedClaim, VerifiedClaim
from code_claim_verifier.security import _normalize_claim_path, safe_path

_GENERATED_MARKERS = [
    "DO NOT EDIT", "AUTO-GENERATED", "GENERATED BY", "Code generated by",
    "@generated", "auto-generated", "THIS FILE IS GENERATED",
]


def _find_file_in_repo(filename: str, repo_path: str) -> str | None:
    """Find a missing claim path, with a narrowly scoped basename fallback."""
    raw_filename = filename.replace("\\", "/") if isinstance(filename, str) else ""
    normalized = _normalize_claim_path(filename)
    if normalized is None:
        return None

    exact = safe_path(normalized, repo_path)
    if exact and os.path.isfile(exact):
        return exact

    # A path such as src/app.py must not silently become a lookup for any
    # app.py in the repository. Basename fallback is only for bare names.
    if "/" in raw_filename:
        return None

    basename = os.path.basename(normalized)
    candidates: list[str] = []
    for root, _dirs, files in os.walk(repo_path, followlinks=False):
        if basename not in files:
            continue
        candidate = os.path.join(root, basename)
        relative = os.path.relpath(candidate, repo_path)
        # safe_path resolves symlinks and rejects candidates outside the repo.
        resolved = safe_path(relative, repo_path)
        if resolved and os.path.isfile(resolved):
            candidates.append(resolved)

    if candidates:
        return sorted(candidates)[0]
    return None


def _resolve_fuzzy_file(path: object, repo_path: str) -> str | None:
    """Resolve a file exactly, then use the safe basename fallback."""
    normalized = _normalize_claim_path(path)
    if normalized is None:
        return None
    resolved = safe_path(normalized, repo_path)
    if resolved is None:
        return None
    if os.path.isfile(resolved):
        return resolved
    return _find_file_in_repo(path, repo_path)


def verify_file_exists(claim: TypedClaim, repo_path: str, language: str) -> VerifiedClaim:
    path = claim.parameters.get("file", claim.parameters.get("path", ""))
    if not path:
        return VerifiedClaim(
            claim=claim, verdict="UNVERIFIABLE", method_confidence=0.0,
            evidence="No file path specified", method="path_check",
        )
    if not isinstance(path, str):
        return VerifiedClaim(
            claim=claim, verdict="UNVERIFIABLE", method_confidence=0.0,
            evidence=f"File path must be a string: {path!r}", method="path_check",
        )
    if _normalize_claim_path(path) is None:
        return VerifiedClaim(claim=claim, verdict="REFUTED", method_confidence=0.99,
                             evidence=f"Invalid path: {path}", method="path_check")
    resolved = safe_path(path, repo_path)
    if resolved is None:
        return VerifiedClaim(claim=claim, verdict="REFUTED", method_confidence=0.99,
                             evidence=f"Path escapes repository: {path}", method="path_check")
    if os.path.isfile(resolved):
        return VerifiedClaim(
            claim=claim, verdict="VERIFIED", method_confidence=0.99,
            evidence=f"exists: {path}", method="os.path.isfile",
        )
    found = _find_file_in_repo(path, repo_path)
    if found:
        return VerifiedClaim(
            claim=claim, verdict="VERIFIED", method_confidence=0.90,
            evidence=f"exists (fuzzy match): {os.path.relpath(found, repo_path)}",
            method="os.walk_fuzzy",
        )
    return VerifiedClaim(
        claim=claim, verdict="REFUTED", method_confidence=0.99,
        evidence=f"not found: {path}", method="os.path.isfile",
    )


def verify_line_content(claim: TypedClaim, repo_path: str, language: str) -> VerifiedClaim:
    path = claim.parameters.get("file", claim.parameters.get("path", ""))
    line_num = claim.parameters.get("line", 0)
    expected = claim.parameters.get(
        "content", claim.parameters.get("expected_content", claim.parameters.get("expected", ""))
    )

    if not path:
        return VerifiedClaim(claim=claim, verdict="UNVERIFIABLE", method_confidence=0.0,
                             evidence="No file path specified", method="file_read")
    if not isinstance(path, str):
        return VerifiedClaim(
            claim=claim, verdict="UNVERIFIABLE", method_confidence=0.0,
            evidence=f"File path must be a string: {path!r}", method="file_read",
        )
    if not isinstance(expected, str):
        return VerifiedClaim(
            claim=claim, verdict="UNVERIFIABLE", method_confidence=0.0,
            evidence=f"Expected line content must be a string: {expected!r}",
            method="file_read",
        )
    expected = expected.strip()
    if not expected:
        return VerifiedClaim(claim=claim, verdict="UNVERIFIABLE", method_confidence=0.0,
                             evidence="No expected line content specified", method="file_read")
    normalized = _normalize_claim_path(path)
    resolved = safe_path(normalized, repo_path) if normalized is not None else None
    if resolved is not None and not os.path.isfile(resolved):
        resolved = _find_file_in_repo(path, repo_path)
    if resolved is None or not os.path.isfile(resolved):
        return VerifiedClaim(claim=claim, verdict="REFUTED", method_confidence=0.95,
                             evidence=(f"Invalid file path: {path}" if normalized is None
                                       else f"File not found: {path}"),
                             method="file_read")
    try:
        with open(resolved, "r", encoding="utf-8", errors="replace") as f:
            lines = f.readlines()
        valid_line = (
            isinstance(line_num, int)
            and not isinstance(line_num, bool)
            and line_num >= 1
        )
        if not valid_line:
            return VerifiedClaim(
                claim=claim, verdict="UNVERIFIABLE", method_confidence=0.0,
                evidence=f"Invalid or missing 1-based line number: {line_num}",
                method="file_read",
            )
        if line_num > len(lines):
            return VerifiedClaim(claim=claim, verdict="REFUTED", method_confidence=0.95,
                                 evidence=f"Line {line_num} out of range (file has {len(lines)} lines)", method="file_read")
        actual = lines[line_num - 1].strip()
        match = expected in actual
        return VerifiedClaim(
            claim=claim, verdict="VERIFIED" if match else "REFUTED",
            method_confidence=0.95,
            evidence=f"Line {line_num}: {actual[:200]}",
            method="file_read",
        )
    except Exception as e:
        return VerifiedClaim(claim=claim, verdict="UNVERIFIABLE", method_confidence=0.0,
                             evidence="", method="file_read", error=str(e)[:200])


def verify_file_classification(claim: TypedClaim, repo_path: str, language: str) -> VerifiedClaim:
    path = claim.parameters.get("file", claim.parameters.get("path", ""))
    expected_cat = (claim.parameters.get("category", "")
                    or claim.parameters.get("classification", "")).lower()

    normalized_path = _normalize_claim_path(path)
    resolved = safe_path(normalized_path, repo_path) if normalized_path is not None else None
    if resolved is None or not os.path.isfile(resolved):
        return VerifiedClaim(
            claim=claim, verdict="UNVERIFIABLE", method_confidence=0.0,
            evidence=(f"Invalid file path: {path}" if normalized_path is None
                      else f"File not found: {path}"),
            method="path_check",
        )

    test_patterns = [r"test[s_/]", r"_test\.", r"\.test\.", r"spec[s_/]", r"e2e/", r"integration/", r"fixtures?/"]
    vendor_patterns = [r"vendor/", r"third_party/", r"node_modules/"]
    header_patterns = [r"\.h$", r"\.hpp$", r"\.hh$"]

    path_lower = normalized_path.lower()
    is_test = any(re.search(p, path_lower) for p in test_patterns)
    is_vendor = any(re.search(p, path_lower) for p in vendor_patterns)
    is_header = any(re.search(p, path_lower) for p in header_patterns)

    _CATEGORY_MAP = {
        "test": "test", "testing": "test", "unit_test": "test", "test_file": "test",
        "production": "production", "source": "production", "implementation": "production",
        "code": "production", "main": "production",
        "vendored": "vendored", "vendor": "vendored", "third_party": "vendored",
        "header": "header", "include": "header",
        "config": "config", "configuration": "config", "build": "config",
    }
    normalized = _CATEGORY_MAP.get(expected_cat, expected_cat)

    if normalized == "test":
        match = is_test
    elif normalized == "vendored":
        match = is_vendor
    elif normalized == "production":
        match = not is_test and not is_vendor
    elif normalized == "header":
        match = is_header
    elif normalized == "config":
        config_patterns = [r"config", r"\.cfg$", r"\.ini$", r"\.yaml$", r"\.yml$", r"makefile", r"cmake"]
        match = any(re.search(p, path_lower) for p in config_patterns)
    else:
        match = not is_test and not is_vendor

    return VerifiedClaim(
        claim=claim, verdict="VERIFIED" if match else "REFUTED",
        method_confidence=0.80, evidence=f"path={path}, is_test={is_test}, is_vendor={is_vendor}",
        method="path_regex",
    )


def verify_generated_or_vendored(claim: TypedClaim, repo_path: str, language: str) -> VerifiedClaim:
    path = claim.parameters.get("file", claim.parameters.get("path", ""))
    expected = claim.parameters.get("expected", True)

    if not isinstance(path, str) or not path:
        return VerifiedClaim(
            claim=claim, verdict="UNVERIFIABLE", method_confidence=0.0,
            evidence=f"File path must be a non-empty string: {path!r}",
            method="header_check",
        )

    normalized = _normalize_claim_path(path)
    resolved = safe_path(normalized, repo_path) if normalized is not None else None
    if resolved is not None and not os.path.isfile(resolved):
        found = _find_file_in_repo(normalized, repo_path)
        if found:
            resolved = found
    if resolved is None or not os.path.isfile(resolved):
        return VerifiedClaim(claim=claim, verdict="REFUTED", method_confidence=0.85,
                             evidence=(f"Invalid file path: {path}" if normalized is None
                                       else f"File not found: {path}"),
                             method="header_check")

    path_parts = normalized.lower().split("/")
    if any(part in {"vendor", "third_party", "node_modules"} for part in path_parts):
        is_gen = True
    else:
        try:
            with open(resolved, "r", encoding="utf-8", errors="replace") as f:
                header = f.read(1000)
            is_gen = any(m in header for m in _GENERATED_MARKERS)
        except Exception:
            is_gen = False

    match = is_gen == expected
    return VerifiedClaim(
        claim=claim, verdict="VERIFIED" if match else "REFUTED",
        method_confidence=0.85, evidence=f"generated/vendored={is_gen}",
        method="header_check",
    )
